CREATE TABLE IF NOT EXISTS `pre_stk_project_upload` (`asset_id` bigint unsigned NOT NULL AUTO_INCREMENT,`owner_uid` int unsigned NOT NULL,`project_id` bigint unsigned NOT NULL DEFAULT 0,`storage_key` varchar(500) NOT NULL,`mime_type` varchar(64) NOT NULL,`size_bytes` bigint unsigned NOT NULL DEFAULT 0,`status` varchar(16) NOT NULL DEFAULT 'temporary',`expires_at` int unsigned NOT NULL DEFAULT 0,`created_at` int unsigned NOT NULL DEFAULT 0,`updated_at` int unsigned NOT NULL DEFAULT 0,PRIMARY KEY (`asset_id`),UNIQUE KEY `uk_storage_key` (`storage_key`(191)),KEY `idx_owner_status` (`owner_uid`,`status`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
