DB::query("INSERT IGNORE INTO %t (owner_uid,project_id,storage_key,mime_type,size_bytes,status,expires_at,created_at,updated_at) SELECT p.publisher_uid,i.project_id,i.storage_key,i.mime_type,i.size_bytes,'bound',0,p.created_at,p.updated_at FROM %t i INNER JOIN %t p ON p.project_id=i.project_id WHERE i.storage_key<>''", ['stk_project_upload','stk_project_image','stk_project']);
